root=Path(__file__).resolve().parents[2];p=root/'research/nine-sharing-sign16-window-assembly-check';draft=root/'research/nine-sharing-sign16-window-assembly-draft';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest();run=p/'run.py';m=p/'source-manifest.json';assert sha(run)=='244982c87b33a036d216e7ea4c7491524694b0df7f9584dab31bac6b07dd0e81' and sha(m)=='8de25aabc5e95b5c1b9edd25d94e21949acc15bd89147bb570c22f09144bec03';row,=json.loads(m.read_text())['rows'];name='Sign16WindowAssembly';src=p/'src/DiophantineConsistency'/(name+'.lean');s=src.read_text();assert sha(src)==sha(draft/(name+'.lean'))==row['source_sha256']=='104ac9b7770ecf4dfebe30874b8d0f6a07b1ec7d6c63940795f16ed234d6dc68' and row['module']=='DiophantineConsistency.'+name and re.findall(r'^import ([A-Za-z0-9_.]+)$',s,re.M)==row['imports']==['DiophantineConsistency.Sign16FirstNorm','DiophantineConsistency.Sign16StrictNorm','DiophantineConsistency.Sign16AuxFromSeed','DiophantineConsistency.Sign16WindowScale','DiophantineConsistency.Sign33Windows'];assert not re.search(r'(?m)^\s*(axiom|opaque)\b|\b(sorry|admit)\b',s)
for t in ('theorem half_window_of_seed','(hp0 :','(hp1 :','(hp2 :','(hp3 :','(hb : 0 < beta) (hMC : MC < beta) (hMF : MF < 2 * beta)','(hz : InternalZero (seed p) v)','2 * Sign16RankValue.Rank beta MC MF v < C beta v','Sign16FirstNorm.first_of_seed','Sign16StrictNorm.strict_of_seed','Sign16AuxFromSeed.auxiliary_of_seed','Sign16WindowScale.scale_of_seed','Sign33Windows.windows_from_maintained_norms'):assert t in s
r=run.read_text();survey=p/'provider-survey.py';assert sha(survey)=='d872b90d302486054b2a36d7cc55780a64a1c88e990806063d68ace0c7f96c81' and "if local in survey['producers']:" in r and "for rel,rec in survey['extra'].items():" in r and "'-M2800'" in r and 'rss_limit=4*1024**3,mem_floor=10*1024**3,seconds=120,interval=.1' in r
checks=[('reviews/nine-sharing-sign16-aux-from-seed-terminal-independent/check.py','dbe89f15a122c337229e88aaf364ab9b7b1b16b618cf64aafa18884f74b97c24'),('reviews/nine-sharing-sign16-first-norm-terminal-independent/check.py','3a8cfcbe7d96b4d588ebeb8abab3e2e722be8a3781c91262388c84ad7fc4ff36'),('reviews/nine-sharing-sign16-strict-norm-retry01-terminal-independent/check.py','80bbb872dcfe879b4535eb531b480cce86fb77dc53095de09e863c8eb0b79e1a'),('reviews/nine-sharing-sign16-window-scale-terminal-independent/check.py','12cc6c532549e247df919798e56bd782bea99cd9a726061ed1879bbf9a0f1dfb'),('reviews/nine-sharing-sign33-windows-retry01-terminal-frontier-independent/check.py','cb43319a1c4a99071d55f00ba03db680b2d206ec59c922410cb2fc1909d17e27')]
for path,pin in checks:
 check=root/path;assert sha(check)==pin;subprocess.run([sys.executable,'-I','-S','-B',str(check)],capture_output=True,check=True,timeout=120)
z=subprocess.run([sys.executable,'-I','-S','-B',str(survey)],capture_output=True,text=True,check=True,timeout=180);data=json.loads(z.stdout);assert data['status']=='PASS' and len(data['extra'])==4 and len(data['producers'])==4
x=subprocess.run([sys.executable,'-I','-S','-B',str(run),'--preflight'],capture_output=True,text=True,timeout=180);assert x.returncode==0 and not x.stderr and json.loads(x.stdout)['status']=='PASS_NO_LEAN_PREFLIGHT'
print(json.dumps({'status':'PASS_PRELAUNCH','runner_sha256':sha(run),'extra_overlays':len(data['extra']),'scope':'conditional half-window from staged seed and explicit beta/port bounds; no V lift'},indent=2,sort_keys=True))
